            { q: "What does a LEFT JOIN return?", opts: ["Only matching rows", "All rows from the left table plus matching rows from the right — NULLs where no match exists", "All rows from both tables", "Only rows where both tables have data"], a: 1, exp: "LEFT JOIN keeps all left table rows. If no match in the right table, columns from the right table are NULL. Essential for finding 'customers with no orders.'" },
            { q: "What is the correct SQL clause order?", opts: ["WHERE → FROM → SELECT → GROUP BY", "SELECT → FROM → WHERE → GROUP BY → HAVING → ORDER BY → LIMIT", "FROM → WHERE → SELECT → ORDER BY", "GROUP BY → SELECT → FROM → WHERE"], a: 1, exp: "SQL clause order is fixed: SELECT, FROM, WHERE, GROUP BY, HAVING, ORDER BY, LIMIT. Execution order differs: FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY." },
            { q: "What does COUNT(DISTINCT column) do?", opts: ["Counts all rows", "Counts the number of unique non-NULL values in a column", "Counts NULL values", "Same as COUNT(*)"], a: 1, exp: "COUNT(DISTINCT customer_id) counts unique customers. Without DISTINCT, COUNT counts all rows including duplicates — giving very different results." },
            { q: "What is a subquery?", opts: ["A smaller database", "A query nested within another query — used in SELECT, FROM, or WHERE clauses", "A saved query template", "A join between two queries"], a: 1, exp: "Subqueries enable complex filtering: 'Find customers whose order value exceeds the average order value' uses a subquery to calculate the average." }
