            { q: "Why should you avoid SELECT * in production queries?", opts: ["* is a syntax error in some databases", "Retrieves unnecessary columns, increases I/O and network transfer, and prevents covering index optimizations", "SELECT * is always fine", "It only matters for large tables"], a: 1, exp: "SELECT * transfers all data. If you need 3 columns from a 100-column table, SELECT * wastes 97 columns of bandwidth and prevents index-only scans." },
            { q: "How do indexes improve query performance?", opts: ["They sort all data automatically", "Indexes allow the database to find rows without scanning the entire table — dramatically reducing I/O", "Indexes use more memory", "Only for PRIMARY KEY columns"], a: 1, exp: "Without an index on email, finding one user requires scanning every row. With an index, the database jumps directly to the matching row — orders of magnitude faster." },
            { q: "What is a covering index?", opts: ["An index covering all tables", "An index containing all columns needed for a query — the database reads only the index, never the table", "A primary key index", "An index on multiple tables"], a: 1, exp: "Covering indexes eliminate table access entirely. If your query needs (customer_id, order_date, revenue) and all three are in one index, the table is never touched." },
            { q: "Why should you avoid applying functions to indexed columns in WHERE?", opts: ["Functions are always slow", "WHERE YEAR(date) = 2024 prevents index use on 'date' column — use date ranges instead", "Functions improve query clarity only", "Database engines handle this automatically"], a: 1, exp: "WHERE YEAR(created_at) = 2024 forces a full table scan. Use WHERE created_at >= '2024-01-01' AND created_at < '2025-01-01' to allow index use." }
